using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Runtime.Serialization.Json;using Frociart;
internal static class ConsoleLogTests {
 static int checks;static void Check(bool b,string why){checks++;if(!b)throw new Exception(why);}
 static string Dec(string value){return Encoding.UTF8.GetString(Convert.FromBase64String(value));}
 static int Main(string[] args){try{string root=args[0];foreach(string line in File.ReadAllLines(Path.Combine(root,"cases.tsv"))){string[] row=line.Split('\t');string code=Dec(row[1]),wanted=Dec(row[3]);string[] input=row[4].Contains("I")?Dec(row[2]).Split(',').Select(Dec).ToArray():new string[0];var d=FlowPseudocode.Decode(code);string before=Convert.ToBase64String(DiagramIO.EncodeDocument(d));var run=new Interpreter(d);int at=0;var accepted=new List<Tuple<string,string,string,string,int>>();
  for(int i=0;i<10000&&run.State!=RuntimeState.Completed&&run.State!=RuntimeState.Error;i++){
   if(run.State==RuntimeState.WaitingForInput){Check(at<input.Length,"Fixture input available");int count=run.ConsoleLog.Count;long revision=run.ConsoleLog.Revision;string variable=run.InputVariable,node=run.CurrentNodeId,scope=run.CurrentFunctionId,prompt=run.InputPrompt;
    if(row[0]!="empty-text"&&row[0]!="unicode"){Check(!run.ProvideInput("NaN"),"Invalid input rejected");Check(run.ConsoleLog.Count==count&&run.ConsoleLog.Revision==revision&&run.State==RuntimeState.WaitingForInput,"Retry never fabricates accepted input");}
    Check(run.ProvideInput(input[at++]),"Valid input accepted");accepted.Add(Tuple.Create(variable,node,scope,prompt,run.Steps));
   }else run.Step();
  }
  Check(run.State==(row[0]=="error-after-input"?RuntimeState.Error:RuntimeState.Completed),"Exact state "+row[0]);Check(run.OutputText.Replace("\r\n","\n")==wanted,"Original output bytes/continuation "+row[0]);var entries=run.ConsoleLog.Snapshot();Check(new string(entries.Select(e=>e.Kind==FlowConsoleLog.EntryKind.Input?'I':'O').ToArray())==row[4],"Chronological accepted I/O "+row[0]);Check(entries.Count(e=>e.Kind==FlowConsoleLog.EntryKind.Input)==at,"No duplicate accepted input");int n=0;foreach(var entry in entries){Check(entry.Step>0&&d.Nodes.Concat(d.Functions==null?Enumerable.Empty<FlowNode>():d.Functions.SelectMany(f=>f.Body.Nodes)).Any(v=>v.Id==entry.NodeId),"Actual executed origin and step");Check(ReferenceEquals(run.ConsoleLog.Find(entry.Sequence),entry),"Stable console identity");if(entry.Kind==FlowConsoleLog.EntryKind.Input){var record=accepted[n++];Check(entry.Variable==record.Item1&&entry.NodeId==record.Item2&&entry.FunctionId==record.Item3&&entry.Prompt==record.Item4&&entry.Step==record.Item5,"Input context captured before advance");}}
  var outputs=entries.Where(e=>e.Kind==FlowConsoleLog.EntryKind.Output).ToList();Check(outputs.Select(e=>e.Text).SequenceEqual(run.Output)&&outputs.Select(e=>e.Newline).SequenceEqual(run.OutputNewlines),"Exact output event flags and values");if(row[0]=="nested")Check(entries[1].FunctionName=="chiedi"&&entries[1].FunctionId==d.Functions[0].Id,"Nested input scope");if(row[0]=="vector")Check(entries[0].Variable=="v[1]","Indexed input target");
  string transcript=run.ConsoleLog.ToText();File.WriteAllText(Path.Combine(root,"pc-"+row[0]+".txt"),transcript,new UTF8Encoding(false));Check(Convert.ToBase64String(DiagramIO.EncodeDocument(d))==before,"No runtime history in project persistence");int steps=run.Steps;string output=run.OutputText;var state=run.State;string vars=String.Join(";",run.Variables.Select(v=>v.Key+":"+ValueFormatter.Format(v.Value)));long oldSequence=entries.Count==0?0:entries[entries.Count-1].Sequence;run.ConsoleLog.Clear();Check(run.ConsoleLog.Count==0&&run.ConsoleLog.Discarded==0&&run.ConsoleLog.ToText()=="","Explicit clear resets only transcript");Check(run.Steps==steps&&run.State==state&&run.OutputText==output&&String.Join(";",run.Variables.Select(v=>v.Key+":"+ValueFormatter.Format(v.Value)))==vars,"Clear preserves complete execution state");Check(entries.Count==row[4].Length&&run.ConsoleLog.Find(oldSequence)==null,"Snapshots remain immutable after clear");run.Reset();Check(run.ConsoleLog.Count==0&&run.Steps==0&&run.OutputText=="","Reset starts a fresh console");Console.WriteLine("PASS console "+row[0]);
 }
 var log=new FlowConsoleLog();for(int i=0;i<10000;i++)log.Add(FlowConsoleLog.EntryKind.Output,"",null,null,"n",null,"Principale",i,true);Check(log.Count==FlowConsoleLog.MaxEntries&&log.Discarded==10000-FlowConsoleLog.MaxEntries,"Bounded ring retains latest events");Check(log[0].Step==10000-FlowConsoleLog.MaxEntries&&log[log.Count-1].Step==9999,"Eviction preserves chronological tail");Check(log.ToText().Contains("messaggi precedenti rimossi"),"Text export discloses retention limit");long sequence=log[0].Sequence;log.Clear();log.Add(FlowConsoleLog.EntryKind.Input,"x","?","x","n",null,"Principale",1,true);Check(log.Find(sequence)==null,"Clear cannot reuse old sequence identity");
 log.Clear();for(int i=0;i<1000;i++)log.Add(FlowConsoleLog.EntryKind.Input,new string('a',2048),"Domanda","nome","n",null,"Principale",i,true);Check(log.Count<1000&&log.Discarded>0&&log.Snapshot().Sum(e=>e.Cost)<=FlowConsoleLog.MaxCharacters,"Character memory bound covers input history");Check(log[log.Count-1].Step==999,"Bounded transcript retains most recent input");log.Clear();log.Add(FlowConsoleLog.EntryKind.Output,new string('a',FlowConsoleLog.MaxCharacters-12)+"🐢Z",null,null,"n",null,"Principale",1,false);Check(log.Count==1&&log[0].TextLimited&&log.ToText().Contains("Testo limitato"),"Defensive truncation is explicit");Check(log[0].Text.Length==0||!Char.IsHighSurrogate(log[0].Text[log[0].Text.Length-1]),"Truncation never splits UTF-16 pair");
 Console.WriteLine("CONSOLE_PC_CORE PASS checks="+checks);return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
}

